function checkBurnerTemperature(temperatureLimitV) 
{ 
    if ( DiagnosticTelemetry.tcBurner > temperatureLimitV) 
    { 
        burnerOverLimitSecs = burnerOverLimitSecs + 1; 
        if ( burnerOverLimitSecs >= parameters.burnerTemperatureLimitDurationSecs ) 
        { 
            throw "Burner temperature limit exceeded for specified duration"; 
        } 
    } 
    else 
    { 
        burnerOverLimitSecs = 0; 
    } 
